func (s Schema) ResolveAlias(name string) (Field, bool) {
	field, ok := s.Fields[name]
	if !ok {
		return Field{}, false
	}
	if field.Kind == FieldKindVirtualAlias {
		target, ok := s.Fields[field.AliasFor]
		if !ok {
			return Field{}, false
		}
		return target, true
	}
	return field, true
}

